export default function (pi: any) {
  pi.registerCommand("labels", { description: "Label the session", handler: async (_args: string, ctx: any) => {
    const entries = ctx.sessionManager.getEntries();
    const user = entries.find((entry: any) => entry.type === "message" && entry.message.role === "user");
    const answer = entries.find((entry: any) => entry.type === "message" && entry.message.role === "assistant");
    pi.setLabel(user.id, "start");
    pi.setLabel(answer.id, "answer caf\u00e9 <&> \u2028");
  } });
}

